-- PT108-S3-Q26. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT108-S3-Q26$batch06$ AND q.stimulus=$batch06$Anthropologist: After mapping the complete dominance hierarchy for a troupe of vervet monkeys by examining their pairwise interaction, we successfully predicted more complex forms of their group behavior by assuming that each monkey had knowledge of the complete hierarchy. Since our prediction was so accurate, it follows that the assumption we used to reach it was in fact true.

Primatologist: Although I agree that your assumption helped you make those predictions, your conclusion does not follow. You might as well argue that since we can predict the output of some bank cash machines by assuming that these machines actually want to satisfy the customers' requests, these cash machines must really have desires.$batch06$ AND q.prompt=$batch06$Which one of the following is a point about which the anthropologist and the primatologist are committed to disagreeing?$batch06$ AND q.correct_choice=$batch06$D$batch06$) THEN RAISE EXCEPTION 'Question changed: PT108-S3-Q26'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT108-S3-Q26$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT108-S3-Q26'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT108-S3-Q26$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Anthropologist's Position$batch06$, $batch06$The predictions were so accurate that the assumption behind them (each monkey knows the full hierarchy) must be true.$batch06$), (1, $batch06$Primatologist's Position$batch06$, $batch06$The assumption helped the predictions, but that does not prove it is true, any more than predicting cash machines proves they have desires.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The primatologist agrees the predictions worked. What they reject is the step from "useful for prediction" to "true." So the disagreement is whether the successful predictions are enough to show the monkeys knew the hierarchy.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Whether the successful predictions are enough to show the monkeys knew the hierarchy.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT108-S3-Q26$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The primatologist concedes the predictions were successful.$batch06$), ($batch06$B$batch06$, $batch06$The cash machine is the primatologist's comparison. Neither speaker disputes whether machine output can be predicted.$batch06$), ($batch06$C$batch06$, $batch06$This is the most popular wrong answer. The anthropologist says the monkeys do know the hierarchy. But the primatologist never says they *cannot*. They only say the evidence does not prove it. "Unproven" is not "false."$batch06$), ($batch06$D$batch06$, $batch06$The anthropologist says the predictions are sufficient grounds. The primatologist says the conclusion "does not follow."$batch06$), ($batch06$E$batch06$, $batch06$Generalizing to all vervet monkeys never comes up.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT108-S3-Q26$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
